package config

import (
    "fmt"
    "strconv"
    "strings"
)

func ParsePort(raw string) (uint16, error) {
    value := strings.TrimSpace(raw)
    n, err := strconv.ParseUint(value, 10, 16)
    if err != nil {
        return 0, fmt.Errorf("parse port %q: %w", raw, err)
    }
    if n == 0 {
        return 0, fmt.Errorf("port must be between 1 and 65535")
    }
    return uint16(n), nil
}

