package retry

func ShouldRetry(status, attempt int) bool {
    if attempt >= 3 {
        return false
    }
    switch {
    case status == 408:
        return true
    case status == 429:
        return true
    case status >= 500 && status <= 599:
        return true
    default:
        return false
    }
}
